import{_ as p,o as t,c as o,ag as b}from"./chunks/framework.KxDd3USm.js";const c=JSON.parse('{"title":"12.6 课后考题","description":"","frontmatter":{},"headers":[],"relativePath":"12-数学与多媒体/90-课后考题.md","filePath":"12-数学与多媒体/90-课后考题.md"}'),n={name:"12-数学与多媒体/90-课后考题.md"};function s(a,r,e,i,g,B){return t(),o("div",null,[...r[0]||(r[0]=[b('<h1 id="_12-6-课后考题" tabindex="-1">12.6 课后考题 <a class="header-anchor" href="#_12-6-课后考题" aria-label="Permalink to &quot;12.6 课后考题&quot;">​</a></h1><blockquote><p>先独立完成，再翻到文件末尾核对。计算题必须写单位。</p></blockquote><h3 id="一、选择题-15-题" tabindex="-1">一、选择题（15 题） <a class="header-anchor" href="#一、选择题-15-题" aria-label="Permalink to &quot;一、选择题（15 题）&quot;">​</a></h3><p><strong>1.</strong> 从 8 名候选人中选 3 人组成不区分职务的评审组，共有（ ）种选法。</p><p>A. 24<br> B. 56<br> C. 336<br> D. 512</p><p><strong>2.</strong> 用数字 0–9 组成允许重复的 4 位验证码（可以以 0 开头），共有（ ）种。</p><p>A. 40<br> B. 1000<br> C. 9000<br> D. 10000</p><p><strong>3.</strong> 命题 <code>P→Q</code> 为假的唯一情况是（ ）。</p><p>A. P 真、Q 真<br> B. P 真、Q 假<br> C. P 假、Q 真<br> D. P 假、Q 假</p><p><strong>4.</strong> 一棵含 12 个顶点的无向树有（ ）条边。</p><p>A. 10<br> B. 11<br> C. 12<br> D. 66</p><p><strong>5.</strong> 某无向图所有顶点的度数之和为 28，该图有（ ）条边。</p><p>A. 7<br> B. 14<br> C. 28<br> D. 56</p><p><strong>6.</strong> 真值为 20.00，近似值为 19.80，其绝对误差和百分相对误差分别为（ ）。</p><p>A. 0.20，1%<br> B. 0.20，0.01%<br> C. 1.00，0.20%<br> D. 1.00，1%</p><p><strong>7.</strong> 一幅 1024×768、24 bit 的未压缩图像约占（ ）。</p><p>A. 0.75 MiB<br> B. 2.25 MiB<br> C. 18 MiB<br> D. 24 MiB</p><p><strong>8.</strong> 一幅图像需要表示不超过 256 种颜色，每个像素至少需要（ ）。</p><p>A. 4 bit<br> B. 7 bit<br> C. 8 bit<br> D. 16 bit</p><p><strong>9.</strong> 44.1 kHz、16 bit、双声道 PCM 音频录制 10 秒，未压缩容量为（ ）。</p><p>A. 441000 B<br> B. 882000 B<br> C. 1764000 B<br> D. 14112000 B</p><p><strong>10.</strong> 某带限声音的最高频率为 8 kHz，按照采样定理，理想最低采样频率为（ ）。</p><p>A. 4 kHz<br> B. 8 kHz<br> C. 12 kHz<br> D. 16 kHz</p><p><strong>11.</strong> 最适合描述显示器发光颜色、属于加色模型的是（ ）。</p><p>A. RGB<br> B. CMYK<br> C. YUV<br> D. MIDI</p><p><strong>12.</strong> YUV/YCbCr 中的 Y 主要表示（ ）。</p><p>A. 黄色<br> B. 亮度<br> C. 饱和度<br> D. 透明度</p><p><strong>13.</strong> 典型 JPEG 编码中造成主要信息损失的步骤是（ ）。</p><p>A. 文件命名<br> B. 量化<br> C. Huffman 熵编码<br> D. 写入文件头</p><p><strong>14.</strong> 需要无损保存带 Alpha 透明通道的界面图标，较合适的格式是（ ）。</p><p>A. PNG<br> B. JPEG<br> C. MP3<br> D. MPEG</p><p><strong>15.</strong> MPEG 视频压缩能够取得较高压缩比，一个重要原因是它利用了相邻帧之间的（ ）。</p><p>A. 语法冗余<br> B. 时间冗余<br> C. 权限继承<br> D. 数据库冗余</p><h3 id="二、综合计算题-2-题" tabindex="-1">二、综合计算题（2 题） <a class="header-anchor" href="#二、综合计算题-2-题" aria-label="Permalink to &quot;二、综合计算题（2 题）&quot;">​</a></h3><p><strong>16. 图像与视频容量</strong></p><p>某素材库包含 10 幅 <code>800×600</code>、24 bit 的未压缩彩色图片。</p><p>（1）求 10 幅图片的原始总容量（B 和 MiB）。<br> （2）若采用某有损编码后压缩比为 20:1，求压缩后的总容量（B 和 MiB）。<br> （3）若将同样规格的图像以 25 fps 连续播放 8 秒，不考虑音频，求未压缩视频容量（B 和 MiB）。</p><p><strong>17. 组合、概率与音频容量</strong></p><p>一个测试组有 5 名开发人员和 3 名测试人员。</p><p>（1）从 8 人中任选 3 人组成应急小组，共有多少种选法？<br> （2）若要求小组恰有 1 名测试人员，共有多少种选法？随机任选 3 人时，恰有 1 名测试人员的概率是多少？<br> （3）会议录音采用 48 kHz、24 bit、双声道 PCM，时长 60 秒，求未压缩容量（B 和 MiB）。</p><hr>',41)])])}const d=p(n,[["render",s]]);export{c as __pageData,d as default};
